-- 3) Materi: update 4 baris lama, insert 2 baru
UPDATE materi SET
  type = 'html',
  metadata = '{"title_id":"Sejarah Virus","title_en":"History of Viruses","video_url":""}',
  summary_id = 'Virus pertama diselidiki pada penyakit mosaik tembakau (1883). Mayer menduga bakteri sangat kecil; Ivanovsky membuktikan agen lolos saringan bakteri; Beijerinck menyebutnya virus lolos saring; Stanley (1935) mengkristalkan TMV.',
  summary_en = 'Viruses were first investigated in tobacco mosaic disease (1883). Mayer suspected tiny bacteria; Ivanovsky proved the agent passed bacterial filters; Beijerinck called it a filterable virus; Stanley (1935) crystallized TMV.',
  content_id = '<section><h3>Awal Penemuan</h3><p>Virus berasal dari bahasa latin <em>virion</em> yang artinya racun. Sejarah penemuan virus dimulai 1883 saat ditemukan penyakit yang menyebabkan bintik kuning pada daun tembakau. Beberapa ilmuwan yang terlibat:</p><h4>a. Adolf Mayer (1883)</h4><p>Mayer meneliti penyebab penyakit mosaik pada tanaman tembakau — bercak pada daun yang menghambat pertumbuhan. Ia menyemprotkan getah tembakau sakit ke tembakau sehat, dan tanaman sehat menjadi sakit. Lewat mikroskop ia tidak melihat bakteri penyebabnya, sehingga menduga penyakit disebabkan bakteri yang jauh lebih kecil dari biasanya.</p><h4>b. Dmitri Ivanovsky (1892)</h4><p>Ilmuwan Rusia ini menyaring getah tembakau sakit dengan saringan khusus penahan bakteri. Filtratnya tetap menularkan penyakit mosaik ke tembakau sehat. Ia berkesimpulan penyebabnya bakteri patogenik sangat kecil atau bakteri penghasil toksin yang mampu lolos saringan.</p><h4>c. Martinus Beijerinck (1897)</h4><p>Beijerinck membuktikan agen penginfeksi dalam getah tembakau dapat berkembang biak: getah yang disaring dipakai menginfeksi tanaman baru secara berulang dan daya patogennya tidak berkurang. Agen itu tidak bisa tumbuh pada medium nutrisi dalam cawan petri dan tidak dinonaktifkan alkohol — berbeda dengan bakteri. Ia memperkirakan agen tersebut partikel lebih kecil dan sederhana dari bakteri: <strong>virus lolos saring (filterable virus)</strong>.</p><h4>d. Wendell Stanley (1935)</h4><p>Ilmuwan Amerika ini berhasil <strong>mengkristalkan</strong> partikel penginfeksi tembakau, yang dikenal sebagai <em>tobacco mosaic virus</em> (TMV). Penemuan bahwa virus dapat dikristalkan menjadi berita menarik sekaligus membingungkan — ciri khas benda mati ada pada "agen penyakit".</p></section>',
  content_en = '<section><h3>Early Discoveries</h3><p>Virus comes from the Latin <em>virion</em> meaning poison. Virus research began in 1883 with a yellow-spot disease on tobacco leaves. Key scientists:</p><h4>a. Adolf Mayer (1883)</h4><p>Mayer studied tobacco mosaic disease — leaf spots that stunt growth. Sap from sick plants sprayed onto healthy ones made them sick too, yet no bacteria were visible under the microscope, so he suspected unusually small bacteria.</p><h4>b. Dmitri Ivanovsky (1892)</h4><p>He filtered sap from diseased tobacco through bacteria-retaining filters; the filtrate still caused mosaic disease, suggesting bacteria-tiny pathogens or toxin producers.</p><h4>c. Martinus Beijerinck (1897)</h4><p>Beijerinck proved the infectious agent could reproduce: serially sprayed filtrate kept infecting plant after plant without losing potency. The agent could not grow on nutrient agar and resisted alcohol — unlike bacteria. He called it a <strong>filterable virus</strong>.</p><h4>d. Wendell Stanley (1935)</h4><p>He <strong>crystallized</strong> the infective particle, known as <em>tobacco mosaic virus</em> (TMV) — a striking, confusing discovery blending living and non-living traits.</p></section>'
WHERE bab_id = 'virus' AND sub_bab_key = 'sub.virus1';

UPDATE materi SET
  type = 'html',
  metadata = '{"title_id":"Ciri-Ciri Virus","title_en":"Virus Traits","video_url":""}',
  summary_id = 'Virus tidak masuk kingdom manapun karena memiliki ciri unik antara benda mati dan makhluk hidup: berkisar 20-300 nm, tubuh hanya kapsid + asam nukleat, dan berreproduksi hanya di dalam sel hidup.',
  summary_en = 'Viruses fit no kingdom due to unique traits mixing non-living and living: 20-300 nm, body of capsid + nucleic acid alone, and reproduction only inside living cells.',
  content_id = '<section><h3>Sifat Unik Virus</h3><p>Virus tidak dimasukkan dalam kingdom manapun pada klasifikasi makhluk hidup karena memiliki ciri unik — kombinasi sifat benda mati dan makhluk hidup. Cirinya:</p><ul><li>Berukuran sangat kecil sekitar 0,02–0,3 μm; hanya dapat dilihat dengan <strong>mikroskop elektron</strong>.</li><li>Tubuh terdiri atas <strong>kapsid</strong> dan <strong>materi genetik</strong> — berupa DNA atau RNA saja.</li><li>Tidak mempunyai membran dan organel sel yang penting bagi kehidupan.</li><li>Hanya dapat bereproduksi bila berada dalam <strong>sel hidup atau jaringan hidup</strong>.</li><li>Dapat <strong>mengkristal</strong> seperti benda mati.</li><li>Bentuk bermacam-macam: batang, bola, bulat, peluru, atau berbentuk T.</li><li>Aktivitasnya dapat dihilangkan oleh <strong>sinar ultraviolet dan sinar X</strong>, tetapi antibiotik dan bahan antibakteri lain tidak berpengaruh.</li></ul><p>Sifat-sifat inilah yang membuat posisi virus spesial: <em>kristalisasi</em> menempatkannya pada alam benda mati, sementara kemampuan bereproduksi di sel hidup menempatkannya pada alam makhluk hidup.</p></section>',
  content_en = '<section><h3>Unique Traits</h3><p>Viruses fit no kingdom because of their unique mix of non-living and living traits:</p><ul><li>Extremely small, about 0.02–0.3 μm — visible only by <strong>electron microscope</strong>.</li><li>Body made of a <strong>capsid</strong> plus <strong>genetic material</strong> — DNA or RNA only.</li><li>No membrane nor life-essential organelles.</li><li>Reproduce only inside <strong>living cells or tissues</strong>.</li><li>Can <strong>crystallize</strong> like non-living matter.</li><li>Various shapes: rod, spherical, round, bullet, or T-shaped.</li><li>Inactivated by <strong>ultraviolet light and X-rays</strong>, but antibiotics and antibacterial substances have no effect.</li></ul><p>Crystallization places viruses in the non-living realm, while reproduction inside living cells proves their living aspect.</p></section>'
WHERE bab_id = 'virus' AND sub_bab_key = 'sub.virus2';

UPDATE materi SET
  type = 'html',
  metadata = '{"title_id":"Struktur dan Fungsi Virus","title_en":"Virus Structure and Function","video_url":""}',
  summary_id = 'Tubuh virus bukan sel. Partikel lengkap = virion: kapsid (kapsomer) pelindung genom, asam nukleat tunggal, sampul membran (virus berenvelop), dan ekor bakteriofag dengan jarum penusuk.',
  summary_en = 'The virus body is not a cell. A complete particle = virion: protective capsid (capsomeres), single nucleic acid, envelope (enveloped viruses), and bacteriophage tail with a needle.',
  content_id = '<section><h3>Struktur Tubuh Virus</h3><p>Struktur tubuh virus berbeda dengan sel organisme hidup. Tubuh virus <strong>bukan suatu sel</strong> karena tidak memiliki dinding sel, membran sel, sitoplasma, inti sel, dan organel lainnya. Partikel virus yang lengkap disebut <strong>virion</strong>. Virus bakteriofag berbentuk huruf T memiliki bagian berikut:</p><img src="/images/virus/struktur-virus.svg" alt="Diagram struktur virus bakteriofag" /><h4>a. Kapsid dan Selubung Ekor</h4><p><strong>Kapsid</strong> adalah selubung terluar virus yang tersusun dari banyak subunit protein yang disebut <strong>kapsomer</strong>. Kapsid memberi bentuk virus — polihedral, batang, bulat, oval, dan lainnya. Protein penyusun selubung ekor sama jenisnya dengan penyusun kapsid. Fungsinya: melindungi materi genetik dari kerusakan serta membantu proses pengenalan dan perlekatan ke sel inang.</p><h4>b. Asam Nukleat</h4><p>Virus hanya mengandung <strong>satu jenis</strong> asam nukleat: DNA atau RNA. Asam nukleat menyusun genom yang berfungsi sebagai informasi genetik saat replikasi. Genom virus dapat berupa DNA untai ganda, DNA untai tunggal, atau RNA untai tunggal; bentuknya linear tunggal, sirkuler, bersegmen, atau tidak bersegmen.</p><h4>c. Sampul Membran (Envelope)</h4><p>Beberapa virus memiliki selubung tambahan — <strong>sampul membran</strong> — tersusun atas lipid, karbohidrat, atau glikoprotein. Fungsinya sebagai pelindung yang berkaitan dengan antigen dan sistem imun virus. Virus Sindbis salah satu contohnya. Lipid penyusun sampul diperoleh saat nukleokapsid melakukan penjubungan melalui membran sel inang. Virus tanpa sampul disebut <strong>virus telanjang</strong>.</p><h4>d. Ekor</h4><p>Ekor berfungsi <strong>menempel pada sel inang</strong>, tersusun atas serabut ekor dan lempeng dasar. <strong>Serabut ekor</strong> menempelkan virus pada sel inang; <strong>lempeng dasar</strong> berisi jarum penusuk yang menginjeksi DNA ke dalam sel inang. Pada virus lain, seperti <em>Coronavirus</em>, bagian penempel reseptor inang adalah <strong>protein spike</strong>.</p></section>',
  content_en = '<section><h3>Virus Body Structure</h3><p>Virus structure differs from living cells: a virus body <strong>is not a cell</strong> — no cell wall, membrane, cytoplasm, nucleus, or organelles. A complete particle is a <strong>virion</strong>. A T-shaped bacteriophage has:</p><img src="/images/virus/struktur-virus.svg" alt="Bacteriophage structure diagram" /><h4>a. Capsid and Tail Sheath</h4><p>The <strong>capsid</strong> is the outer shell made of protein subunits called <strong>capsomeres</strong>; it defines the virus shape (polyhedral, rod, round, oval, etc.) and protects the genome while aiding host-cell recognition and attachment.</p><h4>b. Nucleic Acid</h4><p>A virus contains <strong>one kind only</strong>: DNA or RNA. The nucleic acid forms the genome carrying genetic information for replication — double-stranded DNA, single-stranded DNA, or single-stranded RNA, linear, circular, segmented, or not.</p><h4>c. Membrane Envelope</h4><p>Some viruses carry a <strong>membrane envelope</strong> of lipids, carbohydrates, or glycoproteins, related to antigens and immune evasion (e.g., Sindbis virus). Lipids are acquired when the nucleocapsid buds through the host membrane. Viruses without envelopes are <strong>naked</strong>.</p><h4>d. Tail</h4><p>The tail attaches the virus to the host cell, made of tail fibers and a base plate. Tail fibers anchor to the host; the base plate holds a <strong>needle that injects DNA</strong>. In other viruses such as <em>Coronavirus</em>, host-receptor binding uses <strong>spike proteins</strong>.</p></section>'
WHERE bab_id = 'virus' AND sub_bab_key = 'sub.virus3';

UPDATE materi SET
  type = 'html',
  metadata = '{"title_id":"Cara Hidup dan Reproduksi Virus","title_en":"Virus Life and Reproduction","video_url":""}',
  summary_id = 'Virus = parasit intraseluler obligat; mengenali inang via lock and key. Siklus litik: adsorbsi–penetrasi–sintesis–pematangan–lisis. Siklus lisogenik: profag terintegrasi dan dibawa saat sel membelah.',
  summary_en = 'Viruses are obligate intracellular parasites honing in via lock-and-key. Lytic cycle: adsorption–penetration–synthesis–maturation–lysis. Lysogenic: prophage integrates and is inherited when the cell divides.',
  content_id = '<section><h3>Parasit Intraseluler Obligat</h3><p>Virus hanya dapat hidup di dalam sel hidup organisme tertentu yang cocok — disebut <strong>parasit intraseluler obligat</strong>. Bila sel yang ditumpanginya mati, virus juga mati. Sel hidup yang ditumpangi disebut <strong>sel inang</strong>. Virus mengidentifikasi sel inang menggunakan <strong>kesesuaian (lock and key)</strong>. Kisaran inang bisa luas — flu burung menginfeksi aves dan manusia — atau sempit, seperti bakteriofag yang hanya menginfeksi <em>E. coli</em>.</p><h3>Penularan Virus</h3><h4>a. Langsung</h4><p>Tanpa vektor: melalui udara, air, darah, lendir, dan media lain. Contoh: penyakit polio, cacar, herpes, dan campak.</p><h4>b. Tidak Langsung</h4><p>Dengan vektor: contoh <em>Flavivirus</em> penyebab demam berdarah yang membutuhkan nyamuk <em>Aedes aegypti</em>.</p><h3>Siklus Litik</h3><img src="/images/virus/siklus-litik.svg" alt="Diagram siklus litik" /><p>Terdapat ketika pertahanan sel inang lebih lemah dari daya infeksi virus, sehingga tahapan berlangsung cepat. Virus yang bereproduksi dengan cara ini disebut <strong>virus virulen</strong>; sel inang pecah dan mati serta terbentuk virion-virion baru.</p><ul><li><strong>Adsorbsi:</strong> virion menempel pada reseptor spesifik sel inang dengan serabut ekornya. Ada-tidaknya reseptor menentukan patogenesitas — polio hanya melekat pada sel saraf pusat dan saluran usus primata; HIV berikatan dengan reseptor T CD4.</li><li><strong>Penetrasi:</strong> selubung ekor berkontraksi menembus dinding dan membran sel; DNA virus diinjeksikan, kapsid menjadi kosong.</li><li><strong>Sintesis:</strong> DNA sel inang dihidrolisis; materi genetik virus mengendalikan pembuatan asam nukleat dan protein komponen virus.</li><li><strong>Pematangan (perakitan):</strong> hasil sintesis dirakit menjadi virion-virion lengkap.</li><li><strong>Lisis:</strong> virus menghasilkan lisozim perusak dinding sel inang; air masuk secara osmosis, sel membesar lalu pecah — virion baru menyerang sel inang lain.</li></ul><h3>Siklus Lisogenik</h3><img src="/images/virus/siklus-lisogenik.svg" alt="Diagram siklus lisogenik" /><p>Terdapat jika pertahanan sel inang lebih baik dari daya infeksi virus: sel tidak segera pecah, bahkan membelah normal. DNA virus bakteriofag berinteraksi dengan kromosom sel inang membentuk <strong>profag</strong>. Saat sel membelah, profag diwariskan ke sel anakan. Perbuatannya yang khas: <em>tidak</em> terbentuk virion baru; sel inang tidak rusak. Tahapannya: adsorbsi → penetrasi → <strong>penggabungan</strong> (DNA virus menyatu dengan DNA inang; hampir semua gen profag nonaktif kecuali gen pengkode protein reseptor) → <strong>pembelahan</strong> (profag tewarisan; dapat terinduksi aktif) → <strong>sintesis</strong> (profag keluar dari kromosom, DNA inang hancur, dilanjutkan siklus litik).</p><p>Virus yang dapat bereproduksi dengan daur litik dan lisogenik disebut <strong>virus temperat</strong>, misalnya <em>fag λ</em>.</p></section>',
  content_en = '<section><h3>Obligate Intracellular Parasite</h3><p>Viruses live only inside suitable living cells — <strong>obligate intracellular parasites</strong>. If the host dies, the virus dies too. The cell it inhabits is the <strong>host cell</strong>, identified via <strong>lock-and-key</strong> matching. Host ranges: broad (bird flu infects aves and humans) or narrow (bacteriophages infect only <em>E. coli</em>).</p><h3>Transmission</h3><h4>a. Direct</h4><p>No vector: through air, water, blood, mucus. Examples: polio, smallpox, herpes, measles.</p><h4>b. Indirect</h4><p>Vectored: e.g., <em>Flavivirus</em> (dengue) needs the <em>Aedes aegypti</em> mosquito.</p><h3>Lytic Cycle</h3><img src="/images/virus/siklus-litik.svg" alt="Lytic cycle diagram" /><p>Runs when host defenses are weaker than viral infectivity — fast. Viruses reproducing this way are <strong>virulent</strong>; the host bursts, releasing new virions.</p><ul><li><strong>Adsorption:</strong> the virion attaches to specific receptors with its tail fibers (polio binds CNS and primate gut cells; HIV binds T CD4).</li><li><strong>Penetration:</strong> the sheath contracts to pierce wall and membrane; viral DNA is injected, leaving an empty capsid.</li><li><strong>Synthesis:</strong> host DNA is hydrolyzed; viral genome directs production of viral nucleic acids and proteins.</li><li><strong>Maturation:</strong> components assemble into complete virions.</li><li><strong>Lysis:</strong> lysozyme breaks the wall; osmotic inflow swells and bursts the cell — new virions attack other hosts.</li></ul><h3>Lysogenic Cycle</h3><img src="/images/virus/siklus-lisogenik.svg" alt="Lysogenic cycle diagram" /><p>Occurs when host defenses resist infection: the cell neither bursts nor stops dividing. Phage DNA integrates into the host chromosome as a <strong>prophage</strong>, inherited at cell division. No new virions form; the host stays intact. Stages: adsorption → penetration → <strong>integration</strong> (viral DNA joins host DNA; nearly all prophage genes stay silent except the receptor-protein gene) → <strong>division</strong> (prophage is inherited and can be induced) → <strong>synthesis</strong> (prophage leaves the chromosome, host DNA degrades — the lytic cycle follows).</p><p>Phages capable of both cycles are <strong>temperate</strong>, e.g. <em>phage λ</em>.</p></section>'
WHERE bab_id = 'virus' AND sub_bab_key = 'sub.virus4';


INSERT INTO materi (bab_id, sub_bab_key, sort_order, type, summary_id, summary_en, content_id, content_en, metadata)
VALUES
('virus', 'sub.virus5', 5, 'html',
 'Klasifikasi dilihat dari asam nukleat, ukuran, morfologi, simetri, enzim, inang, dll. ICTV: famili -viridae, genus -virus, spesies berakhiran -virus.',
 'Classification by nucleic acid, size, morphology, symmetry, enzymes, host, etc. ICTV: family -viridae, genus -virus, species ending in -virus.',
 '<section><h3>Dasar Pengelompokkan</h3><p>Klasifikasi virus dilakukan berdasarkan: jenis asam nukleat, ukuran dan morfologi, jenis simetri, jumlah kapsomer, ada tidaknya membran sampul, kerentanan terhadap pengaruh kimia dan fisika, kandungan enzim tertentu, sifat imunologis, jenis sel inang, cara penularan alamiah, serta simtomatologi.</p><h3>Berdasarkan Jenis Asam Nukleat</h3><h4>a. Virus DNA</h4><p>Contoh: <em>Parvovirus</em>, <em>Papovavirus</em>, <em>Adenovirus</em>, <em>Herpesvirus</em>.</p><h4>b. Virus RNA</h4><p>Contoh: <em>Picornavirus</em>, <em>Togavirus</em>, <em>Flavivirus</em>, <em>Calicivirus</em>, <em>Coronavirus</em>, <em>Paramyxovirus</em>, <em>Rhabdovirus</em>.</p><h3>Berdasarkan Ukuran</h3><h4>a. Virus kecil</h4><p>Diameter ±20 nm (lebih kecil dari ribosom), misalnya <em>Poliovirus</em> yang menyerang susunan saraf pusat.</p><h4>b. Virus besar</h4><p>Ukuran 150–300 nm atau lebih, misalnya <em>Parainfluenza virus</em> yang menyerang saluran pernapasan.</p><h3>Berdasarkan Morfologi</h3><img src="/images/virus/bentuk-virus.svg" alt="Bentuk-bentuk virus" /><p>Morfologi virus dibedakan menjadi: bulat (sferis), filamen, kompleks (T), batang, peluru, dan polihedral.</p><h3>Taksonomi ICTV</h3><p>Sistem <strong>ICTV</strong> (International Committee on Taxonomy of Viruses) menggunakan 3 tingkatan takson: <strong>famili</strong>, <strong>genus</strong>, dan <strong>spesies</strong>.</p><ul><li>Famili berakhiran <strong>-viridae</strong> — contoh: <em>Poxviridae</em>.</li><li>Genus berakhiran <strong>-virus</strong> — contoh: <em>Orthopoxvirus</em>.</li><li>Spesies dalam bahasa Inggris berakhiran <strong>-virus</strong> — contoh: <em>Variola virus</em> (penyebab cacar).</li></ul><p>Nama genus dan spesies dicetak miring.</p></section>',
 '<section><h3>Basis of Grouping</h3><p>Viruses are classified by: nucleic acid type, size and morphology, symmetry, capsomere count, presence of an envelope, susceptibility to chemicals and physical agents, certain enzymes, immunological properties, host cell type, natural transmission, and symptomatology.</p><h3>By Nucleic Acid</h3><h4>a. DNA Viruses</h4><p>Examples: <em>Parvovirus</em>, <em>Papovavirus</em>, <em>Adenovirus</em>, <em>Herpesvirus</em>.</p><h4>b. RNA Viruses</h4><p>Examples: <em>Picornavirus</em>, <em>Togavirus</em>, <em>Flavivirus</em>, <em>Calicivirus</em>, <em>Coronavirus</em>, <em>Paramyxovirus</em>, <em>Rhabdovirus</em>.</p><h3>By Size</h3><h4>a. Small</h4><p>Around 20 nm — smaller than ribosomes — e.g., <em>Poliovirus</em> attacking the CNS.</p><h4>b. Large</h4><p>150–300 nm or more, e.g., <em>Parainfluenza virus</em> attacking the respiratory tract.</p><h3>By Morphology</h3><img src="/images/virus/bentuk-virus.svg" alt="Virus shapes" /><p>Virus morphology includes: spherical, filamentous, complex (T-shaped), rod, bullet, and polyhedral.</p><h3>ICTV Taxonomy</h3><p>The <strong>ICTV</strong> (International Committee on Taxonomy of Viruses) uses three taxon ranks: <strong>family</strong>, <strong>genus</strong>, and <strong>species</strong>.</p><ul><li>Family ends in <strong>-viridae</strong> — e.g., <em>Poxviridae</em>.</li><li>Genus ends in <strong>-virus</strong> — e.g., <em>Orthopoxvirus</em>.</li><li>Species ends in <strong>-virus</strong> — e.g., <em>Variola virus</em> (smallpox).</li></ul><p>Genus and species names are italicized.</p></section>',
 '{"title_id":"Bentuk dan Klasifikasi Virus","title_en":"Virus Shapes and Classification","video_url":""}');

INSERT INTO materi (bab_id, sub_bab_key, sort_order, type, summary_id, summary_en, content_id, content_en, metadata)
VALUES
('virus', 'sub.virus6', 6, 'html',
 'Virus menguntungkan: terapi gen, vaksin, pengobatan biologis, bioinsektisida. Merugikan: penyakit manusia (gondongan sampai SARS), hewan (rabies, PMK, tetelo), dan tumbuhan (TYLC, tungro, mosaik).',
 'Benefits: gene therapy, vaccines, biological therapy, bioinsecticides. Harms: human diseases (mumps to SARS), animal (rabies, FMD, Newcastle), plant (TYLC, tungro, mosaic).',
 '<section><h3>Peranan yang Menguntungkan</h3><p>Sebagian besar virus merugikan karena cara hidupnya bersifat <strong>parasit intraseluler obligat</strong>. Namun beberapa dimanfaatkan untuk kesejahteraan manusia:</p><ul><li><strong>Teknologi rekayasa genetika (terapi gen):</strong> <em>Retrovirus</em> dipakai sebagai vektor memasukkan gen pengkode enzim AD ke dalam sel limfosit T yang abnormal.</li><li><strong>Pembuatan vaksin:</strong> selubung virus dipakai sebagai protein khusus yang memacu pembentukan respons kekebalan terhadap penyakit.</li><li><strong>Pengobatan biologis:</strong> membasmi atau melemahkan bakteri, jamur, atau protozoa patogen.</li><li><strong>Pembasmi serangga hama:</strong> virus parasit serangga dibiakkan untuk menyemprot hama tanaman — <em>Baculovirus</em> digunakan sebagai bioinsektisida bebas pencemar lingkungan sejak 1950.</li></ul><h3>Peranan yang Merugikan</h3><p>Virus menyebabkan penyakit pada manusia, hewan, maupun tumbuhan.</p><h4>Penyakit pada Manusia</h4><ul><li><strong>Gondongan</strong> — <em>Paramyxovirus</em>: pembengkakan kelenjar parotis (kelenjar ludah); nyeri lebih terasa bila menelan makanan asam.</li><li><strong>Herpes</strong> — <em>Herpes simpleks virus</em> (HSV-1 dan HSV-2): infeksi sel epitel; virus tetap laten pada sel saraf; menyebabkan lepuh berisi cairan; menular lewat kontak langsung dengan cairan epitel terinfeksi.</li><li><strong>Cacar variola</strong> — <em>Variolavirus</em>: inkubasi ±12 hari; demam dan lesu 1–5 hari, diikuti vesikula → pustula → kerak → parut merah muda yang lambat memudar. Dicegah dengan vaksin <em>Orthopoxvirus</em>.</li><li><strong>Cacar air</strong> — virus <em>varisela</em>: penyakit ringan yang mudah menular terutama pada anak-anak; ditandai vesikula pada kulit dan selaput lendir.</li><li><strong>Hepatitis</strong> — virus hepatitis: gangguan fungsi hati dan saluran empedu hingga dapat kematian; menular lewat cairan tubuh atau peralatan makan-minum penderita.</li><li><strong>Influenza</strong> — virus influenza: menggigil, sakit kepala, batuk kering, demam, nyeri otot menyeluruh.</li><li><strong>Campak</strong> — <em>Morbillivirus</em>: inkubasi 7–11 hari; demam, bersin, batuk, pilek, mata merah, ruam bercak cokelat. Satu kali infeksi memberi kekebalan seumur hidup; endemik, berulang tiap 2–3 tahun; dicegah dengan vaksin.</li><li><strong>AIDS</strong> — <em>HIV</em> (genus <em>Lentivirus</em>): menyerang limfosit T CD4 sehingga hilangnya imunitas. Perkembangan panjang (±10 tahun): infeksi primer → penyebaran ke organ limfoid → laten klinis → ekspresi HIV → penyakit klinis → kematian (±2 tahun sesudah). Gejala: diare kronis, penurunan berat badan, lelah, demam, sesak napas, bercak putih pada lidah.</li><li><strong>Demam berdarah</strong> — <em>Flavivirus</em> (virus dengue): menggigil, sakit kepala, nyeri punggung, sendi, otot, dan bola mata; suhu normal 5–6 hari lalu naik 5–8 hari kemudian; bercak merah 24–72 jam; trombosit turun; stadium berat bisa kematian.</li><li><strong>Ebola</strong> — <em>Ebolavirus</em>: muncul pertama di Zaire, Afrika Tengah, 1976; diduga dari hewan terinfeksi ke manusia; menyerang makrofag darah putih dan jaringan fibroblas, menyebar ke organ lain → pendarahan dan kematian.</li><li><strong>Flu burung</strong> — <em>HPAIV</em> (strain H5N1): virus tipe A, ukuran 90–120 nm, famili <em>Orthomyxoviridae</em>; inkubasi 1–7 hari; demam, sakit tenggorokan, batuk, lender dari hidung, nyeri otot, kepala, lemas → sesak napas, radang paru.</li><li><strong>SARS</strong> — <em>SARS virus</em>: gangguan akut saluran pernapasan yang dapat mematikan; demam tinggi, menggigil, lesu, sakit kepala, nyeri otot, batuk kering, sesak napas hingga kekurangan oksigen. Pertama muncul di Guangzhou, China selatan, menyebar ke Hongkong, Taiwan, Singapura, Vietnam, Malaysia, Indonesia.</li></ul><h4>Penyakit pada Hewan</h4><ul><li><strong>Rabies</strong> — <em>Rhabdovirus</em>: infeksi akut susunan saraf pusat; menular melalui gigitan atau liur hewan penderita (anjing, serigala, rubah, tikus, kucing, kelelawar, kambing); gejala: sakit kepala, muntah, mual, demam, halusinasi, kaku otot, sekresi keringat dan air liur meningkat.</li><li><strong>Penyakit mulut dan kuku (PMK)</strong> — <em>Aphthovirus</em>: sangat menular pada ternak sapi, domba, kambing, kerbau, dan hewan berkuku belah (gajah); gejala: kelesuan, gelisah, dehidrasi, malas berdiri, pincang, demam hingga 41°C, liar, nafsu makan turun, vesikula pada mulut; dicegah dengan vaksinasi.</li><li><strong>Tetelo</strong> — virus <em>NCD</em>: penyakit unggas; gejala diare, batuk-batuk, kehilangan keseimbangan sehingga tubuh berputar-putar dengan kepala tertekuk.</li></ul><h4>Penyakit pada Tumbuhan</h4><ul><li><strong>TYLC</strong> (<em>tomato yellow leaf curl virus</em>): daun tomat menguning dan menggulung, hasil panen turun.</li><li><strong>Tungro</strong> — famili <em>Caulimoviridae</em>: menyerang padi; sel-sel daun mati, pertumbuhan terganggu; ditularkan wereng cokelat dan hijau.</li><li><strong>Mosaik</strong> — virus mosaic: pada tembakau, kacang tanah, papaya, cabai, tomat, dan kentang; bercak-bercak kuning pada daun.</li></ul></section>',
 '<section><h3>Beneficial Roles</h3><p>Most viruses are harmful as <strong>obligate intracellular parasites</strong>, but some serve human welfare:</p><ul><li><strong>Genetic engineering (gene therapy):</strong> <em>Retrovirus</em> vectors introduce AD-enzyme coding genes into abnormal T lymphocytes.</li><li><strong>Vaccine production:</strong> virus envelopes supply specific proteins that stimulate immune responses.</li><li><strong>Biological therapy:</strong> weakening or eliminating pathogenic bacteria, fungi, and protozoa.</li><li><strong> Pest control:</strong> insect-parasitic viruses are cultivated and sprayed on crops — <em>Baculovirus</em>, an eco-friendly bioinsecticide since 1950.</li></ul><h3>Harmful Roles</h3><h4>Human Diseases</h4><ul><li><strong>Mumps</strong> — <em>Paramyxovirus</em>: swelling of parotid glands; worse when eating sour foods.</li><li><strong>Herpes</strong> — <em>HSV-1/HSV-2</em>: epithelial infection; virus stays latent in nerves; fluid-filled blisters; direct-contact spread.</li><li><strong>Smallpox</strong> — <em>Variola</em>: ~12-day incubation; fever and fatigue 1–5 days; vesicles → pustules → crusts → pink scars. Prevented by <em>Orthopoxvirus</em> vaccine.</li><li><strong>Chickenpox</strong> — varicella virus: mild, highly contagious, mostly children; vesicles on skin and mucosa.</li><li><strong>Hepatitis</strong> — hepatitis virus: liver and bile dysfunction, can be fatal; body fluids or utensils.</li><li><strong>Influenza</strong> — influenza virus: chills, headache, dry cough, fever, muscle aches.</li><li><strong>Measles</strong> — <em>Morbillivirus</em>: 7–11-day incubation; fever, sneezing, cough, runny nose, red eyes, brown rashes; one infection gives lifelong immunity; endemic, recurring every 2–3 years; vaccine-preventable.</li><li><strong>AIDS</strong> — <em>HIV</em> (genus <em>Lentivirus</em>): attacks T CD4 lymphocytes, destroying immunity. Long course (~10 years): primary infection → lymphoid spread → clinical latency → HIV expression → clinical disease → death (~2 years later). Symptoms: chronic diarrhea, weight loss, fatigue, fever, breathlessness, white tongue patches.</li><li><strong>Dengue hemorrhagic fever</strong> — <em>Flavivirus</em> (dengue): chills, headache, back/joint/muscle/eye-socket pain; temperature normalizes 5–6 days then spikes 5–8 days later; red patches 24–72 hours; falling platelets; critical cases fatal.</li><li><strong>Ebola</strong> — <em>Ebolavirus</em>: first appeared in Zaire, Central Africa, 1976; suspected animal-to-human transmission; attacks macrophages and fibroblasts, spreading to organs → hemorrhage and death.</li><li><strong>Bird flu</strong> — <em>HPAIV</em> (H5N1): type A orthomyxovirus, 90–120 nm; 1–7-day incubation; fever, sore throat, cough, runny nose, muscle and head aches, weakness → breathlessness, lung inflammation.</li><li><strong>SARS</strong> — <em>SARS virus</em>: acute, potentially fatal respiratory illness; high fever, chills, fatigue, headache, muscle pain, dry cough, breathlessness; first in Guangzhou, southern China, spreading to Hong Kong, Taiwan, Singapore, Vietnam, Malaysia, Indonesia.</li></ul><h4>Animal Diseases</h4><ul><li><strong>Rabies</strong> — <em>Rhabdovirus</em>: acute CNS infection; spread by bites or saliva of infected animals (dog, wolf, fox, rat, cat, bat, goat); symptoms: headache, vomiting, nausea, fever, hallucinations, muscle stiffness, increased sweat and saliva.</li><li><strong>Foot-and-mouth disease</strong> — <em>Aphthovirus</em>: highly contagious in cattle, sheep, goats, buffalo, and cloven-hoofed wildlife like elephants; lethargy, agitation, dehydration, reluctance to stand, limping, fever up to 41°C, excess saliva, appetite loss, blisters; vaccine-preventable.</li><li><strong>Newcastle disease</strong> — <em>NCD</em> virus: in poultry; diarrhea, coughing, loss of balance with head-twisting circling.</li></ul><h4>Plant Diseases</h4><ul><li><strong>TYLC</strong> (<em>tomato yellow leaf curl virus</em>): tomato leaves turn yellow and curl, lowering yields.</li><li><strong>Tungro</strong> — family <em>Caulimoviridae</em>: attacks rice; leaf cell death disturbs growth; spread by brown and green plant hoppers.</li><li><strong>Mosaic</strong> — mosaic virus: on tobacco, peanut, papaya, chili, tomato, potato; yellow leaf patches.</li></ul></section>',
 '{"title_id":"Peranan Virus dalam Kehidupan","title_en":"Roles of Viruses in Life","video_url":""}');

